'use strict';

const fs = require('fs');
const path = require('path');
const { estimateTokens, minifyText } = require('../core/tokens');
const { extractSkeletonWithMeta } = require('../skeleton');

const SOURCE_EXT = new Set([
    '.dart', '.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.vue', '.svelte',
    '.kt', '.kts', '.java', '.swift', '.m', '.mm',
    '.py', '.pyw', '.go', '.rs', '.php', '.rb', '.erb', '.cs',
    '.c', '.h', '.cpp', '.cc', '.cxx', '.hpp', '.scala', '.groovy',
    '.ex', '.exs', '.hs', '.lua', '.sql',
    '.yaml', '.yml', '.toml', '.json', '.jsonc', '.xml', '.gradle',
    '.html', '.htm', '.css', '.scss', '.sass', '.less',
    '.sh', '.bash', '.zsh', '.ps1', '.bat', '.cmd',
]);

/**
 * @param {string} fsPath
 */
function isSourceFile(fsPath) {
    if (/node_modules|[/\\]\.git[/\\]|[/\\]build[/\\]|[/\\]dist[/\\]|[/\\]\.oxygen[/\\]/.test(fsPath)) {
        return false;
    }
    return SOURCE_EXT.has(path.extname(fsPath).toLowerCase());
}

/**
 * @param {typeof import('vscode')} vscode
 * @param {string} workspaceRoot
 * @param {(rel: string, fsPath: string, text: string) => object | null} processFn
 */
async function indexWorkspace(vscode, workspaceRoot, processFn) {
    const uris = await vscode.workspace.findFiles('**/*', '**/{node_modules,.git,build,dist,.oxygen}/**', 5000);
    /** @type {object[]} */
    const entries = [];

    for (const uri of uris) {
        const fsPath = uri.fsPath;
        if (!isSourceFile(fsPath) || !fsPath.startsWith(workspaceRoot)) {
            continue;
        }
        try {
            const text = fs.readFileSync(fsPath, 'utf8');
            if (text.length < 40) {
                continue;
            }
            const result = processFn(fsPath, text);
            if (result) {
                entries.push(result);
            }
        } catch {
            // skip unreadable
        }
    }

    return entries;
}

/**
 * @param {object} opts
 */
function buildContextBundle(opts) {
    const {
        activeFile,
        activeSkeleton,
        activeOriginalTokens,
        scopeLabel,
        sessionSavedUSD,
        sessionSavedTokens,
        pricingLabel,
        projectMapExcerpt,
        selectionMinified,
    } = opts;

    const skelTokens = estimateTokens(activeSkeleton ?? '');
    const saved = Math.max(0, (activeOriginalTokens ?? 0) - skelTokens);

    const parts = [
        '# Oxygen Context Bundle',
        '',
        `Pricing: ${pricingLabel}`,
        `Session saved: ~${sessionSavedTokens.toLocaleString()} tokens ($${sessionSavedUSD.toFixed(4)})`,
        scopeLabel ? `Scope: ${scopeLabel}` : '',
        activeFile ? `Active: ${activeFile}` : '',
        '',
        '## Rules (token saver)',
        '- Use skeletons below — NOT full file bodies.',
        '- Read `.oxygen/project-map.md` for project overview.',
        '- Prefer skeletons from `.oxygen/skeletons/` when attaching files.',
        '',
    ].filter(Boolean);

    if (selectionMinified) {
        parts.push('## Selection (minified)', '```', selectionMinified, '```', '');
    }

    if (activeSkeleton) {
        parts.push(
            `## Active file skeleton (${skelTokens} tok, saved ${saved} vs full)`,
            '```',
            activeSkeleton.trim(),
            '```',
            ''
        );
    }

    if (projectMapExcerpt) {
        parts.push('## Project map (excerpt)', projectMapExcerpt.trim(), '');
    }

    parts.push('---', '_Generated by Oxygen Token Saver_', '');
    return parts.join('\n');
}

/**
 * @param {string} text
 */
function minifySelection(text) {
    return minifyText(text);
}

module.exports = {
    isSourceFile,
    indexWorkspace,
    buildContextBundle,
    minifySelection,
};
